package com.primehr.succession;

import com.primehr.succession.application.RspReferralSourcePort;
import com.primehr.succession.domain.*;
import org.junit.jupiter.api.Test;

import java.time.*;

import static org.assertj.core.api.Assertions.*;
import static org.mockito.Mockito.*;

class SuccessionContinuityDomainTest {
    @Test void continuityPlanSeparatesSubmitApproveAndFinalizeAndRecordsZeroBenchGap(){var p=plan();p.submit("PLANNER",Instant.now());assertThatThrownBy(()->p.approve("PLANNER","Approved",Instant.now())).isInstanceOf(IllegalArgumentException.class);p.approve("APPROVER","Approved",Instant.now());assertThatThrownBy(()->p.finalizePlan("APPROVER",0,Instant.now())).isInstanceOf(IllegalArgumentException.class);p.finalizePlan("FINALIZER",0,Instant.now());assertThat(p.getCoverageStatus()).isEqualTo(SuccessionContinuityPlan.CoverageStatus.NO_ACTIVE_BENCH);assertThat(p.getStatus()).isEqualTo(SuccessionContinuityPlan.Status.FINALIZED);}
    @Test void referralNeverCreatesAnApplicationAndRequiresSeparatedAuthorization(){var p=mock(SuccessionContinuityPlan.class);when(p.getStatus()).thenReturn(SuccessionContinuityPlan.Status.FINALIZED);when(p.getId()).thenReturn("plan");when(p.getJobPositionId()).thenReturn(10L);when(p.getPositionName()).thenReturn("Chief");var b=bench();var r=new SuccessionRspReferralPacket("A",p,b,"Merit-process referral","You were referred for consideration","Restricted basis","CREATOR");assertThatThrownBy(()->r.authorize("CREATOR","Authorized",Instant.now())).isInstanceOf(IllegalArgumentException.class);r.linkVacancy(new RspReferralSourcePort.VacancySnapshot("pub","vac","PUBLISHED",20L,"Item",10L,"Chief",1L,"Office","profile",1,LocalDate.now(),LocalDate.now().plusDays(10),0,"fp",Instant.now()));r.authorize("AUTHORIZER","Authorized",Instant.now());r.send("SENDER","Sent to RSP",Instant.now());r.receive("RSP","Received",Instant.now());r.updateRspStatus(SuccessionRspReferralPacket.Status.UNDER_REVIEW,"Merit review started");assertThat(r.getStatus()).isEqualTo(SuccessionRspReferralPacket.Status.UNDER_REVIEW);}
    @Test void referralEventHistoryIsAppendOnlyAndSequenced(){var first=new SuccessionRspReferralEvent("A","ref",null,"CREATED","DRAFT","Created","Restricted","ACTOR",Instant.now());var second=new SuccessionRspReferralEvent("A","ref",first,"AUTHORIZED","AUTHORIZED","Authorized","Restricted","HEAD",Instant.now());assertThat(first.getEventSequence()).isOne();assertThat(second.getEventSequence()).isEqualTo(2);assertThat(second.getResultingStatus()).isEqualTo("AUTHORIZED");}
    private static SuccessionContinuityPlan plan(){var risk=mock(SuccessionContinuityRiskReview.class);when(risk.getStatus()).thenReturn(SuccessionContinuityRiskReview.Status.FINALIZED);when(risk.getId()).thenReturn("risk");when(risk.getCycleId()).thenReturn("cycle");when(risk.getDesignationId()).thenReturn("designation");when(risk.getTargetType()).thenReturn("PLANTILLA");when(risk.getTargetId()).thenReturn(20L);when(risk.getJobPositionId()).thenReturn(10L);when(risk.getPositionName()).thenReturn("Chief");when(risk.getPlantillaId()).thenReturn(20L);when(risk.getPlantillaName()).thenReturn("Item");when(risk.getTargetFingerprint()).thenReturn("fp");when(risk.getRiskLevel()).thenReturn(SuccessionContinuityRiskReview.RiskLevel.HIGH);when(risk.getRiskReason()).thenReturn("Single incumbent");var cycle=mock(SuccessionCycle.class);when(cycle.getCharterVersionId()).thenReturn("charter");return new SuccessionContinuityPlan("A",risk,cycle,"Critical functions","Interim arrangement","Continuity actions","Activation triggers",2,LocalDate.now().plusMonths(3));}
    private static SuccessionBenchCoverageEntry bench(){var b=mock(SuccessionBenchCoverageEntry.class);when(b.getId()).thenReturn("bench");when(b.getCandidateId()).thenReturn("candidate");when(b.getPoolDecisionId()).thenReturn("decision");when(b.getMembershipEventId()).thenReturn("membership");when(b.getEmployeeNo()).thenReturn("EMP-1");when(b.getEmployeeName()).thenReturn("Employee One");when(b.getReadinessLevelCode()).thenReturn("READY");when(b.getMembershipExpiresOn()).thenReturn(LocalDate.now().plusMonths(6));return b;}
}
